 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # A 5-bar extends the adjacent colored pattern along its own axis.
    # For vertical bars, take the contiguous multi-row pattern immediately
    # beside the bar and repeat it over the bar's full length.
    vertical_bars = []
    for c in range(w):
        r = 0
        while r < h:
            if g[r][c] != 5:
                r += 1
                continue
            a = r
            while r < h and g[r][c] == 5:
                r += 1
            if r - a >= 2:
                vertical_bars.append((a, r - 1, c))

    for a, b, c in vertical_bars:
        for side in (c - 1, c + 1):
            if not (0 <= side < w):
                continue
            seed_rows = [rr for rr in range(a, b + 1) if g[rr][side] not in (0, 5)]
            if not seed_rows:
                continue
            # The motif occupies a contiguous band of rows touching one end
            # of the bar; use that band as the vertical period.
            lo, hi = min(seed_rows), max(seed_rows)
            if any(g[rr][side] in (0, 5) for rr in range(lo, hi + 1)):
                continue
            motif = [g[rr][side] for rr in range(lo, hi + 1)]
            # Copy the complete adjacent motif width, when present.
            # Infer the contiguous nonzero span on this side for each motif row.
            left = side
            right = side
            for rr in range(lo, hi + 1):
                if side > c:
                    while right + 1 < w and g[rr][right + 1] not in (0, 5):
                        right += 1
                else:
                    while left - 1 >= 0 and g[rr][left - 1] not in (0, 5):
                        left -= 1
            # Keep motif rows in their existing column range, repeat upward/downward.
            cols = range(c + 1, right + 1) if side > c else range(left, c)
            if not cols:
                continue
            pattern = [[g[rr][cc] for cc in cols] for rr in range(lo, hi + 1)]
            for rr in range(a, b + 1):
                pr = (rr - lo) % len(pattern)
                for j, cc in enumerate(cols):
                    if g[rr][cc] == 0:
                        g[rr][cc] = pattern[pr][j]
            break

    # For horizontal bars, the adjacent vertical color sequence is repeated
    # across the bar. The seed is the contiguous nonzero sequence at an endpoint.
    horizontal_bars = []
    for r in range(h):
        c = 0
        while c < w:
            if g[r][c] != 5:
                c += 1
                continue
            a = c
            while c < w and g[r][c] == 5:
                c += 1
            if c - a >= 2:
                horizontal_bars.append((r, a, c - 1))

    for r, a, b in horizontal_bars:
        for edge in (a, b):
            for dr in (-1, 1):
                rr = r + dr
                if not (0 <= rr < h) or g[rr][edge] in (0, 5):
                    continue
                step = dr
                lo = hi = rr
                while 0 <= lo - 1 < h and g[lo - 1][edge] not in (0, 5):
                    lo -= 1
                while 0 <= hi + 1 < h and g[hi + 1][edge] not in (0, 5):
                    hi += 1
                motif = [g[yy][edge] for yy in range(lo, hi + 1)]
                for cc in range(a, b + 1):
                    for yy, color in zip(range(lo, hi + 1), motif):
                        if g[yy][cc] == 0:
                            g[yy][cc] = color
                break
            else:
                continue
            break
    return g
